package com.bank.sanitize;

import java.util.logging.*;

public class StripWhitespaceDemo {
    private static final Logger log = Logger.getLogger("Sanitize");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        SanitizeService service = new SanitizeService();
        log.info(() -> "stream : '" + service.stripWhitespace("SAV 2001\t ") + "'");
        log.info(() -> "regex  : '" + service.stripWhitespaceRegex("SAV 2001\t ") + "'");
    }
}

// ─── Would be in service/SanitizeService.java ───
class SanitizeService {
    // stream approach: filter out whitespace, rebuild string
    String stripWhitespace(String s) {
        return s.chars()
            .filter(c -> !Character.isWhitespace(c))        // Unicode-aware whitespace test
            .mapToObj(c -> String.valueOf((char) c))         // code point → 1-char String
            .collect(java.util.stream.Collectors.joining()); // concat, no separator
    }

    // concise alternative
    String stripWhitespaceRegex(String s) {
        return s.replaceAll("\\s+", "");
    }
}
